	/**
	 * Resolves and validates the configured PHP CLI binary
	 * (AUVOERECHNUNG_PHP_CLI_PATH). Returns null on failure after reporting the
	 * message through handleNonFatal().
	 *
	 * @param int $strict
	 * @return string|null
	 */
	protected function resolvePhpBinary($strict)
	{
		// Without a manual override, auto-detect the CLI binary (cached) using the
		// web runtime's major.minor version, avoiding PHP_BINARY pointing to php-fpm.
		// A bare 'php' (a stale default from older activations) is not a real
		// override, so auto-detect in that case too.
		$manual = trim(getDolGlobalString('AUVOERECHNUNG_PHP_CLI_PATH', ''));
		if ($manual === '' || $manual === 'php') {
			return auvoerechnung_resolve_php_cli($this->db);
		}

		$phpBin = $manual;

		// Hardening: an admin can change this constant through /admin/const.php.
		// escapeshellarg() already prevents shell injection (a malicious value
		// would only result in "command not found"), but reject unusual characters
		// explicitly to catch typos and show a clear error. Allow ':', '\', '(',
		// ')', and spaces for Windows paths (e.g. C:\Program Files\php\php.exe).
		if (!preg_match('#^[A-Za-z0-9/._:() \\\\-]+$#', $phpBin)) {
			dol_syslog('AuVo E-Rechnung: AUVOERECHNUNG_PHP_CLI_PATH value received: '.$phpBin, LOG_ERR);
			$this->handleNonFatal('AuVo E-Rechnung: '.auvoerechnung_trans('AuvoERechnungErrPhpCliChars'), $strict);
			return null;
		}
		// If a directory was entered instead of a binary (common on Windows), append php.exe or php.
		$phpBin = auvoerechnung_php_cli_from_dir($phpBin);

		// For an absolute path, verify that it points to an executable. Allow
		// relative names ("php", "php8.2") for the shell to resolve through PATH.
		if (strpbrk($phpBin, '/\\') !== false && !is_executable($phpBin)) {
			$this->handleNonFatal('AuVo E-Rechnung: '.auvoerechnung_trans('AuvoERechnungErrPhpCliNotFound', $phpBin), $strict);
			return null;
		}

		return $phpBin;
	}

	/**
	 * Embeds Factur-X XML in the PDF using the configured mode
	 * (AUVOERECHNUNG_INJECTION_MODE):
	 *  - 'auto' (default): use in-process, then fall back to a subprocess on failure;
	 *  - 'inprocess': in-process only (never calls exec);
	 *  - 'subprocess': subprocess only (historical behavior).
	 *
	 * @param string $pdfPath    PDF to modify in place
	 * @param string $xmlPath    Temporary XML file to embed
	 * @param string $modulePath Module root directory
	 * @return array{ok:bool,method:string,error:string}
	 */
	protected function injectFacturx($pdfPath, $xmlPath, $modulePath)
	{
		$mode = strtolower(trim(getDolGlobalString('AUVOERECHNUNG_INJECTION_MODE', 'auto')));
		if (!in_array($mode, array('auto', 'inprocess', 'subprocess'), true)) {
			$mode = 'auto';
		}

		// Explicit overrides.
		if ($mode === 'subprocess') {
			return $this->injectSubprocess($pdfPath, $xmlPath, $modulePath);
		}
		if ($mode === 'inprocess') {
			return $this->injectInProcess($pdfPath, $xmlPath, $modulePath);
		}

		// AUTO mode. The isolated PHP subprocess is the safe path and avoids
		// library conflicts. In-process injection can trigger an uncaught fatal
		// compile error if another component (Dolibarr tcpdi or another module
		// bundling setasign/fpdi) has already loaded an incompatible FPDF/FPDI
		// version. A try/catch cannot catch this (seen in production as
		// FpdfTplTrait::setPageFormat). Use in-process only when exec() is
		// unavailable on hardened shared hosting and there is no alternative.
		if (function_exists('exec')) {
			return $this->injectSubprocess($pdfPath, $xmlPath, $modulePath);
		}
		return $this->injectInProcess($pdfPath, $xmlPath, $modulePath);
	}

	/**
	 * IN-PROCESS injection: calls the injection library directly in the current
	 * web process without exec(). Verified to coexist with FPDF/TCPDF (invoice
	 * PDFs use TCPDF; the library uses setasign FPDF). Writes atomically and
	 * never throws; returns a status instead.
	 *
	 * @param string $pdfPath
	 * @param string $xmlPath
	 * @param string $modulePath
	 * @return array{ok:bool,method:string,error:string}
	 */
	protected function injectInProcess($pdfPath, $xmlPath, $modulePath)
	{
		try {
			$pdfContent = @file_get_contents($pdfPath);
			$xmlContent = @file_get_contents($xmlPath);
			if ($pdfContent === false || $xmlContent === false) {
				return array('ok' => false, 'method' => 'inprocess', 'error' => auvoerechnung_trans_raw('AuvoERechnungErrInjReadSource'));
			}

			// Ensure a minimum memory limit for parsing the PDF in memory
			// (best-effort; never lower a higher existing limit).
			$this->ensureMemoryLimit(256 * 1024 * 1024);

			require_once $modulePath.'/vendor/autoload.php';
			if (!class_exists('\\Atgp\\FacturX\\Writer')) {
				return array('ok' => false, 'method' => 'inprocess', 'error' => auvoerechnung_trans_raw('AuvoERechnungErrInjLibMissing'));
			}

			// Prevent a fatal error: if another component has already loaded an
			// FPDF/FPDI class, instantiating the injection library could trigger an
			// uncaught compile error (the try/catch above cannot catch it). Detect
			// this and return cleanly; auto mode will retry through the subprocess.
			$conflict = $this->detectInProcessPdfConflict($modulePath);
			if ($conflict !== null) {
				return array('ok' => false, 'method' => 'inprocess', 'error' => $conflict);
			}

			// AFRelationship 'Alternative' is required by the EN16931 specification
			// (see scripts/inject_facturx.php).
			$writer = new \Atgp\FacturX\Writer();
			$facturxPdf = $writer->generate($pdfContent, $xmlContent, 'en16931', false, array(), false, 'Alternative');
			if (!is_string($facturxPdf) || $facturxPdf === '') {
				return array('ok' => false, 'method' => 'inprocess', 'error' => auvoerechnung_trans_raw('AuvoERechnungErrInjEmptyOutput'));
			}

			// Atomic write: replace the original PDF only after the new file has
			// been written completely.
			$tmpPath = $pdfPath.'.facturx.tmp';
			if (file_put_contents($tmpPath, $facturxPdf) !== strlen($facturxPdf)) {
				@unlink($tmpPath);
				return array('ok' => false, 'method' => 'inprocess', 'error' => auvoerechnung_trans_raw('AuvoERechnungErrInjWriteOutput'));
			}
			if (!@rename($tmpPath, $pdfPath)) {
				@unlink($tmpPath);
				return array('ok' => false, 'method' => 'inprocess', 'error' => auvoerechnung_trans_raw('AuvoERechnungErrInjReplacePdf'));
			}

			return array('ok' => true, 'method' => 'inprocess', 'error' => '');
		} catch (\Throwable $e) {
			return array('ok' => false, 'method' => 'inprocess', 'error' => $e->getMessage());
		}
	}

	/**
	 * Checks whether an FPDF/FPDI class has already been loaded by a component
	 * other than this module's vendor directory (Dolibarr tcpdi or another module
	 * bundling setasign/fpdi). Instantiating the injection library in-process in
	 * that case can trigger an uncaught fatal compile error ("Declaration ...
	 * must be compatible", typically FpdfTplTrait::setPageFormat). Detect this first.
	 *
	 * @param string $modulePath
	 * @return string|null  Conflict message, or null if there is no conflict
	 */
	protected function detectInProcessPdfConflict($modulePath)
	{
		$ourVendor = str_replace('\\', '/', $modulePath).'/vendor/setasign/';

		// Main case: our FpdfTpl extends the global \\FPDF class. Dolibarr also
		// provides \\FPDF in includes/tcpdi/tcpdi.php ("class FPDF extends TCPDF {}").
		// Force autoload of \\FPDF (the parent class only, never FpdfTpl/Fpdi,
		// whose loading could trigger the fatal error) and check which class wins:
		//  - our setasign/fpdf: in-process is safe;
		//  - Dolibarr's FPDF based on TCPDF: guaranteed setPageFormat conflict,
		//    so return cleanly instead of using in-process injection.
		if (class_exists('FPDF', true)) {
			try {
				$file = (new \ReflectionClass('FPDF'))->getFileName();
			} catch (\Throwable $e) {
				$file = false;
			}
			if ($file !== false && strpos(str_replace('\\', '/', $file), $ourVendor) === false) {
				return function_exists('auvoerechnung_trans')
					? auvoerechnung_trans('AuvoERechnungErrTcpdiConflict', basename($file))
					: 'Conflit FPDF/TCPDF (tcpdi de Dolibarr, '.basename($file).') : injection in-process impossible. Activez exec() (mode sous-process) ou posez MAIN_DISABLE_TCPDI=1.';
			}
		}

		// Secondary case: a setasign FPDI class was already loaded by another
		// component. Use autoload=false; do not force these child classes to load.
		foreach (array('setasign\\Fpdi\\FpdfTpl', 'setasign\\Fpdi\\Fpdi') as $cls) {
			if (!class_exists($cls, false)) {
				continue;
			}
			try {
				$file = (new \ReflectionClass($cls))->getFileName();
			} catch (\Throwable $e) {
				continue;
			}
			if ($file !== false && strpos(str_replace('\\', '/', $file), $ourVendor) === false) {
				return auvoerechnung_trans_raw('AuvoERechnungErrInjFpdiConflict', $cls, basename($file));
			}
		}
		return null;
	}

	/**
	 * Injects through a PHP CLI subprocess (historical behavior, isolated from
	 * the web process). Requires exec() and a valid PHP CLI binary.
	 *
	 * @param string $pdfPath
	 * @param string $xmlPath
	 * @param string $modulePath
	 * @return array{ok:bool,method:string,error:string}
	 */
	protected function injectSubprocess($pdfPath, $xmlPath, $modulePath)
	{
		if (!function_exists('exec')) {
			return array('ok' => false, 'method' => 'subprocess', 'error' => auvoerechnung_trans('AuvoERechnungErrNoExec'));
		}
		$phpBin = $this->resolvePhpBinary(0);
		if ($phpBin === null) {
			return array('ok' => false, 'method' => 'subprocess', 'error' => auvoerechnung_trans_raw('AuvoERechnungErrInjNoPhpCli'));
		}

		$cmd  = escapeshellarg($phpBin);
		$cmd .= ' '.escapeshellarg($modulePath.'/scripts/inject_facturx.php');
		$cmd .= ' '.escapeshellarg($pdfPath);
		$cmd .= ' '.escapeshellarg($xmlPath);
		$cmd .= ' 2>&1';

		$output = array();
		$rc = 0;
		exec($cmd, $output, $rc);
		if ($rc !== 0) {
			return array('ok' => false, 'method' => 'subprocess', 'error' => dol_trunc(implode(' ', $output), 300));
		}
		return array('ok' => true, 'method' => 'subprocess', 'error' => '');
	}

	/**
	 * Raises memory_limit to the requested minimum on a best-effort basis and
	 * never lowers it. Does nothing if the limit is unlimited (-1) or ini_set is disabled.
	 *
	 * @param int $minBytes
	 * @return void
	 */
	protected function ensureMemoryLimit($minBytes)
	{
		$cur = @ini_get('memory_limit');
		if ($cur === false || $cur === '' || (string) $cur === '-1') {
			return; // Unlimited or unknown: leave it unchanged.
		}
		$val = trim($cur);
		$unit = strtolower(substr($val, -1));
		$num = (float) $val;
		$bytes = $num;
		if ($unit === 'g') {
			$bytes = $num * 1024 * 1024 * 1024;
		} elseif ($unit === 'm') {
			$bytes = $num * 1024 * 1024;
		} elseif ($unit === 'k') {
			$bytes = $num * 1024;
		}
		if ($bytes > 0 && $bytes < $minBytes) {
			@ini_set('memory_limit', (string) $minBytes);
		}
	}

	/**
	 * Displays the final summary (green if there are no warnings, otherwise orange with the list).
	 *
	 * @param string $invoiceRef
	 * @param array  $warnings
	 */
	protected function reportSuccess($invoiceRef, array $warnings, array $infos = [])
	{
		// No interactive session (REST API, CLI, cron): log only.
		if (!function_exists('setEventMessages') || (php_sapi_name() === 'cli')) {
			return;
		}

		// Informational messages (e.g. XRechnung written) are shown separately
		// and are never counted as warnings.
		foreach ($infos as $info) {
			setEventMessages($info, null, 'mesgs');
		}

		$safeRef = dol_escape_htmltag($invoiceRef);
		if (empty($warnings)) {
			setEventMessages(auvoerechnung_trans('AuvoERechnungMsgSuccess', $safeRef), null, 'mesgs');
			return;
		}

		$msg  = auvoerechnung_trans('AuvoERechnungMsgSuccessWithWarnings', $safeRef, count($warnings)).'<br>';
		$msg .= '<ul style="margin:4px 0 0 0;padding-left:20px;">';
		foreach ($warnings as $w) {
			$msg .= '<li>'.dol_escape_htmltag($w).'</li>';
		}
		$msg .= '</ul>';
		setEventMessages($msg, null, 'warnings');
	}

	/**
	 * Handles a non-fatal hook error:
	 *  - strict mode: reports a blocking error and returns -1;
	 *  - best-effort mode: shows a warning, keeps the regular PDF, and returns 0.
	 *
	 * Note: even in strict mode, the regular PDF already generated by Dolibarr
	 * remains on disk (the hook runs after it is created). Strict mode blocks the
	 * user-facing result, not the file itself.
	 *
	 * @param string $msg           Error message (logged and displayed)
	 * @param int    $strict        0 = best-effort, 1 = blocking strict mode
	 * @param string $fallbackHint  Detail shown in parentheses in best-effort mode
	 * @return int                  -1 (strict) or 0 (best-effort)
	 */
	protected function handleNonFatal($msg, $strict, $fallbackHint = '')
	{
		dol_syslog($msg, LOG_ERR);
		if ($fallbackHint === '') {
			$fallbackHint = auvoerechnung_trans('AuvoERechnungHintPdfKeptShort');
		}
		$interactive = function_exists('setEventMessages') && php_sapi_name() !== 'cli';
		if ($strict) {
			$this->error = $msg;
			$this->errors[] = $msg;
			if ($interactive) {
				setEventMessages($msg, null, 'errors');
			}
			return -1;
		}
		if ($interactive) {
			setEventMessages($msg.' ('.auvoerechnung_trans('AuvoERechnungHintBestEffort').' : '.$fallbackHint.')', null, 'warnings');
		}
		return 0;
	}

	/**
	 * Validates generated XML before embedding it in the PDF.
	 * Step 1: check well-formedness to prevent the injection library from crashing
	 * on malformed XML. Step 2: check Factur-X EN16931 XSD conformance to catch
	 * structural errors before the file reaches a recipient or external validator.
	 *
	 * @param string $xml         XML to validate
	 * @param string $modulePath  Module root (used to locate the bundled XSD)
	 * @return string|null        Error message if invalid, null if valid
	 */
	protected function validateXml($xml, $modulePath)
	{
		// Shared implementation used by the test suites, so tests validate the
		// same code as production (see core/lib/auvoerechnung_rules.php).
		require_once $modulePath.'/core/lib/auvoerechnung_rules.php';
		$xsdPath = $modulePath.'/vendor/atgp/factur-x/xsd/factur-x/en16931/Factur-X_1.09.2_EN16931.xsd';
		if (!file_exists($xsdPath)) {
			dol_syslog('AuVo E-Rechnung: EN16931 XSD missing from vendor/, structural validation limited to well-formedness', LOG_WARNING);
		}
		return auvoerechnung_validate_xsd($xml, $modulePath);
	}
}
